CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT, name TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), central_sid TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS questions (id TEXT PRIMARY KEY, level INTEGER NOT NULL DEFAULT 3, category TEXT NOT NULL, number INTEGER NOT NULL, prompt TEXT NOT NULL, options_json TEXT NOT NULL, answer TEXT NOT NULL, explanation TEXT, concepts_json TEXT, source TEXT NOT NULL, UNIQUE(source, number));
CREATE TABLE IF NOT EXISTS attempts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), mode TEXT NOT NULL, question_ids_json TEXT NOT NULL, answers_json TEXT NOT NULL, score INTEGER NOT NULL, passed INTEGER NOT NULL, started_at TEXT NOT NULL, finished_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS question_stats (user_id TEXT NOT NULL REFERENCES users(id), question_id TEXT NOT NULL REFERENCES questions(id), seen_count INTEGER NOT NULL DEFAULT 0, correct_count INTEGER NOT NULL DEFAULT 0, wrong_count INTEGER NOT NULL DEFAULT 0, mastery REAL NOT NULL DEFAULT 0, last_wrong_at TEXT, PRIMARY KEY(user_id, question_id));
CREATE TABLE IF NOT EXISTS ai_analyses (question_id TEXT PRIMARY KEY REFERENCES questions(id), summary TEXT NOT NULL, concepts_json TEXT NOT NULL, analyzed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS wrong_notes (user_id TEXT NOT NULL REFERENCES users(id), question_id TEXT NOT NULL REFERENCES questions(id), note TEXT NOT NULL, review_prompt TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id, question_id));
CREATE INDEX IF NOT EXISTS idx_questions_category ON questions(category);
